gej(a){return"\u0418\u0437\u0442\u0435\u0433\u043b\u0438"},
gel(){return"\u0422\u043e\u0437\u0438 \u0438\u043c\u0435\u0439\u043b \u043d\u0435 \u0435 \u0432\u0430\u043b\u0438\u0434\u0435\u043d"},
gee(){return"\u0414\u043e\u0431\u0430\u0432\u0435\u0442\u0435 \u0438\u043c\u0435\u0439\u043b"},
geG(){return"\u041a\u0430\u043a\u0432\u043e \u0435 Edhomy AI \u0435\u0437\u0438\u0446\u0438?"},
gek(){return"Edhomy AI languages \u0435 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435, \u0432 \u043a\u043e\u0435\u0442\u043e \u043c\u043e\u0436\u0435\u0442\u0435 \u0434\u0430 \u043d\u0430\u0443\u0447\u0438\u0442\u0435 \u0435\u0437\u0438\u043a \u0441 \u0418\u0418. \u0422\u043e \u043f\u0440\u0435\u0434\u043b\u0430\u0433\u0430 \u0418\u0418 \u0443\u0447\u0438\u0442\u0435\u043b \u0437\u0430 \u043f\u0440\u0430\u043a\u0442\u0438\u043a\u0430 \u043d\u0430 \u043f\u0440\u043e\u0438\u0437\u043d\u043e\u0448\u0435\u043d\u0438\u0435 \u0438 \u043a\u0443\u0440\u0441 \u0437\u0430 \u0440\u0430\u0437\u043a\u0430\u0437\u0432\u0430\u043d\u0435 \u043d\u0430 \u0438\u0441\u0442\u043e\u0440\u0438\u0438 \u0441 100 \u0443\u0440\u043e\u043a\u0430, \u043a\u043e\u0438\u0442\u043e \u0434\u0430 \u0432\u0438 \u043f\u043e\u043c\u043e\u0433\u043d\u0430\u0442 \u0434\u0430 \u043e\u0432\u043b\u0430\u0434\u0435\u0435\u0442\u0435 \u0435\u0437\u0438\u043a\u0430."},
